#!/usr/bin/env python3
"""批量 for-loop：pi agent 优化 Scene → 静态门禁 → Manim 渲染 → ffprobe → 提取成片。

每个知识点在 ``<work-root>/runs/<run_id>/<topic_id>/`` 下独立处理，原仓库文件只在
全部门禁通过且显式加 ``--apply-source`` / ``--extract-to-repo`` 时才回写。

典型用法::

    # 只渲染（不调用 agent），前 3 个初中课题
    python scripts/pipeline/pi_batch.py --level chuzhong --limit 3 --agent none

    # pi agent 优化 + 预览渲染 + 回写通过门禁的源码 + 提取成片到课程目录
    python scripts/pipeline/pi_batch.py --match 第九章-整式 --agent pi \
        --model anthropic/claude-sonnet-4-5 --apply-source --extract-to-repo

    # 续跑同一批次（跳过已成功的课题）
    python scripts/pipeline/pi_batch.py --run-id 20261117-120000 --resume ...

退出码：0 = 全部成功；1 = 至少一个课题失败；2 = 参数/环境错误。
仅依赖 Python 标准库；渲染需要 manim、LaTeX、中文字体与 ffmpeg/ffprobe。
"""
from __future__ import annotations

import argparse
import ast
import concurrent.futures as cf
import datetime as dt
import json
import os
import py_compile
import re
import shlex
import shutil
import subprocess
import sys
import threading
import time
from dataclasses import asdict, dataclass, field
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SKILLS = ROOT / "skills" / "source"
VIDEO_SKILL = SKILLS / "manim-video-production"
CURRICULUM_SKILL = SKILLS / "curriculum-prompt-suite"
DEFAULT_TEMPLATE = Path(__file__).resolve().parent / "prompts" / "optimize_scene.md"
MEDIA_SUFFIXES = {".mp4", ".mov", ".mp3", ".wav", ".gif", ".webm"}
QUALITY_FLAGS = {"l": "-ql", "m": "-qm", "h": "-qh", "p": "-qp", "k": "-qk"}
LEVEL_IDS = ("xiaoxue", "chuzhong", "gaozhong", "external")
_print_lock = threading.Lock()


def log(msg: str) -> None:
    with _print_lock:
        print(f"[{dt.datetime.now():%H:%M:%S}] {msg}", flush=True)


# --------------------------------------------------------------------------- 任务发现
@dataclass
class Lesson:
    topic_id: str
    level: str
    name: str
    py_file: str            # 仓库相对路径
    video_file: str | None  # 仓库相对路径（可能是 _finish.mp4）
    scene: str | None = None

    @property
    def lesson_dir(self) -> str:
        return str(Path(self.py_file).parent)


def iter_catalog(catalog: Path):
    data = json.loads(catalog.read_text(encoding="utf-8"))
    for level in data.get("levels", []):
        level_id = level.get("id", "")

        def walk(node):
            if isinstance(node, dict):
                if "pyFile" in node and node.get("pyFile"):
                    yield node
                for value in node.values():
                    if isinstance(value, (list, dict)):
                        yield from walk(value)
            elif isinstance(node, list):
                for item in node:
                    yield from walk(item)

        for topic in walk(level):
            yield Lesson(
                topic_id=str(topic.get("id") or topic["pyFile"]),
                level=level_id,
                name=str(topic.get("name", "")),
                py_file=topic["pyFile"],
                video_file=topic.get("videoFile"),
            )


def scene_candidates(source: Path) -> list[str]:
    """静态识别文件内（含同文件间接继承）的 Scene 子类，不导入目标代码。"""
    tree = ast.parse(source.read_text(encoding="utf-8"), filename=str(source))
    bases: dict[str, list[str]] = {}
    for node in tree.body:
        if isinstance(node, ast.ClassDef):
            names = []
            for base in node.bases:
                if isinstance(base, ast.Name):
                    names.append(base.id)
                elif isinstance(base, ast.Attribute):
                    names.append(base.attr)
            bases[node.name] = names

    def is_scene(name: str, seen: frozenset = frozenset()) -> bool:
        if name in seen:
            return False
        for base in bases.get(name, []):
            if base.endswith("Scene") or is_scene(base, seen | {name}):
                return True
        return False

    return [name for name in bases if is_scene(name)]


def resolve_scene(lesson: Lesson, source: Path) -> str:
    candidates = scene_candidates(source)
    if not candidates:
        raise ValueError(f"no Scene subclass in {lesson.py_file}")
    if lesson.video_file:
        stem = re.sub(r"_finish$", "", Path(lesson.video_file).stem)
        if stem in candidates:
            return stem
    # 优先不是被其它类继承的“叶子”Scene
    return candidates[-1]


def select_lessons(args) -> list[Lesson]:
    lessons = list(iter_catalog(args.catalog))
    if args.from_list:
        wanted = [line.strip() for line in args.from_list.read_text(encoding="utf-8").splitlines()
                  if line.strip() and not line.startswith("#")]
        by_key = {l.topic_id: l for l in lessons} | {l.py_file: l for l in lessons}
        picked = []
        for key in wanted:
            if key in by_key:
                picked.append(by_key[key])
            elif (ROOT / key).is_file():   # 未进入 catalog 的新文件
                picked.append(Lesson(topic_id=re.sub(r"\W+", "-", key)[-40:], level="adhoc",
                                     name=Path(key).parent.name, py_file=key, video_file=None))
            else:
                log(f"WARN 未找到列表项：{key}")
        lessons = picked
    if args.level:
        lessons = [l for l in lessons if l.level in args.level]
    if args.match:
        lessons = [l for l in lessons if all(m in l.py_file for m in args.match)]
    if args.ids:
        ids = set(args.ids)
        lessons = [l for l in lessons if l.topic_id in ids]
    lessons = lessons[args.offset:]
    if args.limit:
        lessons = lessons[: args.limit]
    return lessons


# --------------------------------------------------------------------------- 运行工具
@dataclass
class Step:
    status: str = "not_run"   # pass / fail / not_run / blocked / skipped
    detail: str = ""
    seconds: float = 0.0
    data: dict = field(default_factory=dict)


def run(cmd: list[str], *, cwd: Path, log_file: Path, timeout: int, env: dict | None = None) -> tuple[int, str]:
    log_file.parent.mkdir(parents=True, exist_ok=True)
    with log_file.open("a", encoding="utf-8") as fh:
        fh.write(f"\n$ (cd {shlex.quote(str(cwd))} && {shlex.join(cmd)})\n")
        fh.flush()
        try:
            proc = subprocess.run(cmd, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                  text=True, timeout=timeout, env=env)
            out = proc.stdout or ""
            fh.write(out)
            return proc.returncode, out
        except subprocess.TimeoutExpired as exc:
            out = (exc.stdout or b"").decode("utf-8", "replace") if isinstance(exc.stdout, bytes) else (exc.stdout or "")
            fh.write(out + f"\n[timeout after {timeout}s]\n")
            return 124, out + f"\n[timeout after {timeout}s]"
        except FileNotFoundError as exc:
            fh.write(f"[not found] {exc}\n")
            return 127, str(exc)


def timed(fn):
    def wrapper(*a, **kw) -> Step:
        start = time.monotonic()
        step = fn(*a, **kw)
        step.seconds = round(time.monotonic() - start, 2)
        return step
    return wrapper


def copy_lesson(src_dir: Path, dst_dir: Path) -> None:
    """复制课程目录中的非媒体文件（源码、描述、分镜、Prompt 等）。"""
    dst_dir.mkdir(parents=True, exist_ok=True)
    for item in src_dir.iterdir():
        if item.name in {"media", "__pycache__"} or item.suffix.lower() in MEDIA_SUFFIXES:
            continue
        if item.is_file():
            shutil.copy2(item, dst_dir / item.name)


def render_template(template: str, values: dict[str, str]) -> str:
    def sub(match: re.Match) -> str:
        key = match.group(1)
        return values.get(key, match.group(0))
    return re.sub(r"\{\{\s*([a-z_]+)\s*\}\}", sub, template)


# --------------------------------------------------------------------------- 单课流水线
class LessonJob:
    def __init__(self, lesson: Lesson, args, run_dir: Path):
        self.lesson = lesson
        self.args = args
        self.dir = run_dir / lesson.topic_id
        self.src_dir = self.dir / "src"
        self.log = self.dir / "pipeline.log"
        self.report_path = self.dir / "report.json"
        self.steps: dict[str, Step] = {}
        self.outputs: dict[str, str] = {}

    # ---- helpers
    @property
    def work_py(self) -> Path:
        return self.src_dir / Path(self.lesson.py_file).name

    @property
    def repo_py(self) -> Path:
        return ROOT / self.lesson.py_file

    def already_done(self) -> bool:
        if not self.report_path.is_file():
            return False
        try:
            return json.loads(self.report_path.read_text(encoding="utf-8")).get("ok") is True
        except ValueError:
            return False

    # ---- steps
    @timed
    def step_prepare(self) -> Step:
        if not self.repo_py.is_file():
            return Step("fail", f"source missing: {self.lesson.py_file}")
        if self.dir.exists():
            shutil.rmtree(self.dir)
        copy_lesson(self.repo_py.parent, self.src_dir)
        shutil.copy2(self.work_py, self.dir / "original.py")
        self.lesson.scene = self.args.scene or resolve_scene(self.lesson, self.work_py)
        return Step("pass", f"scene={self.lesson.scene}")

    def build_prompt(self) -> str:
        l = self.lesson
        lesson_dir = ROOT / l.lesson_dir
        curriculum_prompt = ROOT / ".pi" / "prompts" / "curriculum" / l.lesson_dir / "prompt.txt"
        values = {
            "lesson_path": l.lesson_dir,
            "lesson_name": l.name,
            "scene_file": self.work_py.name,
            "scene_class": l.scene or "",
            "work_dir": str(self.src_dir),
            "repo_root": str(ROOT),
            "video_skill": str(VIDEO_SKILL / "SKILL.md"),
            "curriculum_skill": str(CURRICULUM_SKILL / "SKILL.md"),
            "curriculum_prompt": str(curriculum_prompt) if curriculum_prompt.is_file() else "（无）",
            "description_json": (lesson_dir / "description.json").read_text(encoding="utf-8")
            if (lesson_dir / "description.json").is_file() else "（无 description.json）",
            "has_storyboard": "是" if (lesson_dir / "storyboard.md").is_file() else "否",
            "extra_goal": self.args.goal or "按 SKILL 质量门禁修复数学、布局、动画生命周期问题，提升教学清晰度。",
            "agent_report": "agent_report.json",
        }
        template = self.args.prompt_template.read_text(encoding="utf-8")
        return render_template(template, values)

    @timed
    def step_agent(self) -> Step:
        if self.args.agent == "none":
            return Step("skipped", "--agent none")
        prompt = self.build_prompt()
        agent_dir = self.dir / "agent"
        agent_dir.mkdir(exist_ok=True)
        (agent_dir / "prompt.md").write_text(prompt, encoding="utf-8")
        if self.args.agent == "pi":
            if not shutil.which(self.args.pi_bin):
                return Step("blocked", f"{self.args.pi_bin} not found (npm i -g @mariozechner/pi-coding-agent)")
            cmd = [self.args.pi_bin, "-p", "--no-session", "--no-skills", "--no-prompt-templates",
                   "--skill", str(VIDEO_SKILL), "--skill", str(CURRICULUM_SKILL),
                   "--tools", self.args.pi_tools]
            if self.args.model:
                cmd += ["--model", self.args.model]
            if self.args.provider:
                cmd += ["--provider", self.args.provider]
            if self.args.thinking:
                cmd += ["--thinking", self.args.thinking]
            cmd += [f"@{agent_dir / 'prompt.md'}", "按上面的任务说明执行，最后写出 agent_report.json。"]
        else:  # custom command; {prompt_file} {work_dir} {scene_file} {scene_class} placeholders
            cmd = [part.format(prompt_file=agent_dir / "prompt.md", work_dir=self.src_dir,
                               scene_file=self.work_py.name, scene_class=self.lesson.scene)
                   for part in shlex.split(self.args.agent_cmd)]
        before = self.work_py.read_bytes()
        code, out = run(cmd, cwd=self.src_dir, log_file=agent_dir / "agent.log",
                        timeout=self.args.agent_timeout)
        changed = self.work_py.read_bytes() != before
        report_file = self.src_dir / "agent_report.json"
        report = {}
        if report_file.is_file():
            try:
                report = json.loads(report_file.read_text(encoding="utf-8"))
            except ValueError:
                report = {"_invalid_json": True}
            shutil.move(str(report_file), agent_dir / "agent_report.json")
        # pi 在 API 错误时仍可能返回 0：以产物而非退出码判断
        if code != 0:
            status = "fail"
        elif not report and not changed:
            status = "fail"
        else:
            status = "pass"
        tail = "\n".join(out.strip().splitlines()[-5:])
        return Step(status, f"exit={code} changed={changed} report={'yes' if report else 'no'} | {tail[:400]}",
                    data={"changed": changed, "agent_report": report})

    @timed
    def step_static(self) -> Step:
        data: dict = {}
        try:
            py_compile.compile(str(self.work_py), doraise=True)
        except py_compile.PyCompileError as exc:
            return Step("fail", f"py_compile: {exc.msg[:300]}")
        try:
            if self.lesson.scene not in scene_candidates(self.work_py):
                return Step("fail", f"Scene {self.lesson.scene} disappeared after edit")
        except SyntaxError as exc:
            return Step("fail", f"ast: {exc}")
        scripts = VIDEO_SKILL / "scripts"
        code, out = run([sys.executable, str(scripts / "audit_scene.py"), str(self.work_py), "--json"],
                        cwd=self.src_dir, log_file=self.log, timeout=120)
        try:
            audit = json.loads(out[out.index("{"):])
        except ValueError:
            audit = {"raw": out[-500:]}
        data["audit_scene"] = {k: audit.get(k) for k in ("errors", "warnings")}
        code2, out2 = run([sys.executable, str(scripts / "scan_mathtex.py"), str(self.work_py)],
                          cwd=self.src_dir, log_file=self.log, timeout=120)
        try:
            cjk = json.loads(out2[out2.index("{"):]).get("findings", [])
        except ValueError:
            cjk = []
        data["mathtex_cjk"] = len(cjk)
        errors = (audit.get("errors") or 0) if isinstance(audit, dict) else 0
        if errors and self.args.strict_static:
            return Step("fail", f"audit errors={errors}, mathtex_cjk={len(cjk)}", data)
        return Step("pass", f"audit errors={errors} warnings={audit.get('warnings')} mathtex_cjk={len(cjk)}", data)

    def revert_to_original(self, why: str) -> None:
        shutil.copy2(self.dir / "original.py", self.work_py)
        self.outputs["reverted"] = why
        log(f"  ↺ {self.lesson.topic_id}: 回退原始源码（{why}）")

    @timed
    def step_render(self) -> Step:
        media = self.dir / "render"
        cmd = [sys.executable, "-m", "manim", "render", QUALITY_FLAGS[self.args.quality],
               "-r", self.args.resolution, "--disable_caching", "--media_dir", str(media),
               "--progress_bar", "none", self.work_py.name, self.lesson.scene]
        code, out = run(cmd, cwd=self.src_dir, log_file=self.dir / "render.log",
                        timeout=self.args.render_timeout)
        videos = sorted(media.rglob(f"{self.lesson.scene}.mp4"), key=lambda p: p.stat().st_mtime)
        if code != 0 or not videos or videos[-1].stat().st_size == 0:
            tail = "\n".join(l for l in out.strip().splitlines()[-6:])
            return Step("fail", f"exit={code} | {tail[:600]}")
        self.outputs["raw_video"] = str(videos[-1])
        return Step("pass", str(videos[-1]))

    @timed
    def step_probe(self) -> Step:
        video = Path(self.outputs["raw_video"])
        if not shutil.which("ffprobe"):
            return Step("blocked", "ffprobe not found")
        code, out = run(["ffprobe", "-v", "error", "-print_format", "json", "-show_streams", "-show_format",
                         str(video)], cwd=self.dir, log_file=self.log, timeout=60)
        if code != 0:
            return Step("fail", out[-300:])
        info = json.loads(out)
        vs = next((s for s in info.get("streams", []) if s.get("codec_type") == "video"), {})
        width, height = vs.get("width"), vs.get("height")
        duration = float(info.get("format", {}).get("duration", 0) or 0)
        data = {"width": width, "height": height, "duration": round(duration, 2),
                "fps": vs.get("r_frame_rate"), "has_audio": any(s.get("codec_type") == "audio"
                                                                for s in info.get("streams", []))}
        want_w, want_h = (int(x) for x in self.args.resolution.split(","))
        ok = (width, height) == (want_w, want_h) and duration > 1
        # 首帧/中段/末帧截图，便于人工审片
        frames = self.dir / "frames"
        frames.mkdir(exist_ok=True)
        for tag, t in (("start", 0.5), ("mid", duration / 2), ("end", max(duration - 0.5, 0))):
            run(["ffmpeg", "-hide_banner", "-loglevel", "error", "-y", "-ss", f"{t:.2f}", "-i", str(video),
                 "-frames:v", "1", "-vf", "scale=360:-1", str(frames / f"{tag}.png")],
                cwd=self.dir, log_file=self.log, timeout=60)
        return Step("pass" if ok else "fail", json.dumps(data, ensure_ascii=False), data)

    @timed
    def step_music(self) -> Step:
        if not self.args.music:
            return Step("skipped", "no --music")
        music = self.args.music if self.args.music.is_absolute() else ROOT / self.args.music
        if not music.is_file():
            return Step("blocked", f"music missing: {music}")
        raw = Path(self.outputs["raw_video"])
        out = raw.with_name(f"{self.lesson.scene}_finish.mp4")
        code, text = run(["ffmpeg", "-hide_banner", "-loglevel", "error", "-y", "-i", str(raw), "-i", str(music),
                          "-map", "0:v:0", "-map", "1:a:0", "-c:v", "copy", "-c:a", "aac", "-shortest", str(out)],
                         cwd=self.dir, log_file=self.log, timeout=300)
        if code != 0 or not out.is_file():
            return Step("fail", text[-300:])
        self.outputs["finish_video"] = str(out)
        return Step("pass", str(out))

    @timed
    def step_extract(self) -> Step:
        rel_dir = Path(self.lesson.lesson_dir)
        final_dir = self.args.work_root / "final" / rel_dir
        final_dir.mkdir(parents=True, exist_ok=True)
        copied = []
        for key in ("raw_video", "finish_video"):
            if key in self.outputs:
                src = Path(self.outputs[key])
                shutil.copy2(src, final_dir / src.name)
                copied.append(str(final_dir / src.name))
        self.outputs["final_dir"] = str(final_dir)
        data: dict = {"final": copied}
        if self.args.extract_to_repo:
            repo_dir = ROOT / rel_dir
            placed = []
            for path in map(Path, copied):
                target = repo_dir / path.name
                if target.exists() and not self.args.overwrite:
                    target = repo_dir / f"{path.stem}{self.args.new_suffix}{path.suffix}"
                shutil.copy2(path, target)
                placed.append(str(target.relative_to(ROOT)))
            data["repo"] = placed
        return Step("pass", "; ".join(data.get("repo", copied)), data)

    @timed
    def step_apply(self) -> Step:
        if not self.args.apply_source:
            return Step("skipped", "no --apply-source")
        if self.outputs.get("reverted") or self.steps.get("agent", Step()).status != "pass":
            return Step("skipped", "agent output not accepted")
        if self.work_py.read_bytes() == self.repo_py.read_bytes():
            return Step("skipped", "unchanged")
        shutil.copy2(self.work_py, self.repo_py)
        # agent 可能新增分镜 / 课内数学测试，一并带回（不覆盖已有文件以外的媒体）
        brought = [self.lesson.py_file]
        for item in self.src_dir.iterdir():
            if item.suffix in {".md", ".json", ".py"} and item.name != self.work_py.name \
                    and item.name not in {"agent_report.json"}:
                target = self.repo_py.parent / item.name
                if not target.exists() or target.read_bytes() != item.read_bytes():
                    shutil.copy2(item, target)
                    brought.append(str(target.relative_to(ROOT)))
        return Step("pass", ", ".join(brought), {"files": brought})

    # ---- orchestration
    def execute(self) -> dict:
        l = self.lesson
        started = dt.datetime.now().isoformat(timespec="seconds")
        self.steps["prepare"] = self.step_prepare()
        if self.steps["prepare"].status == "pass":
            self.steps["agent"] = self.step_agent()
            self.steps["static"] = self.step_static()
            if self.steps["static"].status == "fail" and self.steps["agent"].status == "pass":
                self.revert_to_original("static gate failed after agent edit")
                self.steps["agent"].status = "fail"
                self.steps["static"] = self.step_static()
            if self.steps["static"].status != "fail" and not self.args.no_render:
                self.steps["render"] = self.step_render()
                if (self.steps["render"].status == "fail" and self.steps["agent"].status == "pass"
                        and self.args.fallback_original):
                    self.revert_to_original("render failed after agent edit")
                    self.steps["agent"].status = "fail"
                    self.steps["render"] = self.step_render()
                if self.steps["render"].status == "pass":
                    self.steps["probe"] = self.step_probe()
                    self.steps["music"] = self.step_music()
                    if self.steps["probe"].status == "pass":
                        self.steps["extract"] = self.step_extract()
            if self.steps["static"].status == "pass" and (
                    self.args.no_render or self.steps.get("probe", Step()).status == "pass"):
                self.steps["apply"] = self.step_apply()
        required = ["prepare", "static"] + ([] if self.args.no_render else ["render", "probe", "extract"])
        if self.args.agent != "none" and self.args.require_agent:
            required.append("agent")
        ok = all(self.steps.get(name, Step()).status == "pass" for name in required)
        report = {
            "ok": ok, "topic_id": l.topic_id, "level": l.level, "name": l.name,
            "py_file": l.py_file, "scene": l.scene, "started": started,
            "finished": dt.datetime.now().isoformat(timespec="seconds"),
            "steps": {k: asdict(v) for k, v in self.steps.items()},
            "outputs": self.outputs,
            "evidence_note": "静态/渲染/ffprobe 为自动化证据；数学证明、关键帧与音轨仍需人工审查。",
        }
        self.dir.mkdir(parents=True, exist_ok=True)
        self.report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
        return report


# --------------------------------------------------------------------------- 汇总
def write_summary(run_dir: Path, reports: list[dict]) -> Path:
    order = ["prepare", "agent", "static", "render", "probe", "music", "extract", "apply"]
    lines = [f"# 批次 {run_dir.name}", "",
             f"共 {len(reports)} 课，成功 {sum(r['ok'] for r in reports)}，失败 {sum(not r['ok'] for r in reports)}。", "",
             "| 结果 | 课题 | Scene | " + " | ".join(order) + " | 时长(s) |",
             "| --- | --- | --- | " + " | ".join("---" for _ in order) + " | --- |"]
    for r in sorted(reports, key=lambda x: x["py_file"]):
        cells = [r["steps"].get(k, {}).get("status", "—") for k in order]
        dur = r["steps"].get("probe", {}).get("data", {}).get("duration", "")
        lines.append(f"| {'✅' if r['ok'] else '❌'} | {Path(r['py_file']).parent.name} | {r.get('scene') or ''} | "
                     + " | ".join(cells) + f" | {dur} |")
    failures = [r for r in reports if not r["ok"]]
    if failures:
        lines += ["", "## 失败详情", ""]
        for r in failures:
            bad = next((k for k in order if r["steps"].get(k, {}).get("status") in ("fail", "blocked")), "?")
            lines.append(f"- `{r['py_file']}` · {bad}: {r['steps'].get(bad, {}).get('detail', '')[:300]}")
    path = run_dir / "summary.md"
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    with (run_dir / "summary.jsonl").open("w", encoding="utf-8") as fh:
        for r in reports:
            fh.write(json.dumps(r, ensure_ascii=False) + "\n")
    return path


def parse_args(argv=None):
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sel = p.add_argument_group("选择课题")
    sel.add_argument("--catalog", type=Path, default=ROOT / "assets" / "catalog.json")
    sel.add_argument("--level", nargs="+", choices=LEVEL_IDS)
    sel.add_argument("--match", nargs="+", help="pyFile 路径必须包含的子串（可多个，AND）")
    sel.add_argument("--ids", nargs="+", help="catalog topic id")
    sel.add_argument("--from-list", type=Path, help="每行一个 topic id 或仓库相对 .py 路径")
    sel.add_argument("--offset", type=int, default=0)
    sel.add_argument("--limit", type=int, default=0)
    sel.add_argument("--scene", help="强制 Scene 类名（单课调试用）")
    sel.add_argument("--list", action="store_true", help="只列出将处理的课题后退出")

    ag = p.add_argument_group("Agent")
    ag.add_argument("--agent", choices=("pi", "none", "custom"), default="pi")
    ag.add_argument("--agent-cmd", default="", help="--agent custom 时的命令，支持 {prompt_file} {work_dir} {scene_file} {scene_class}")
    ag.add_argument("--pi-bin", default=os.environ.get("PI_BIN", "pi"))
    ag.add_argument("--model", default=os.environ.get("PI_MODEL"))
    ag.add_argument("--provider", default=os.environ.get("PI_PROVIDER"))
    ag.add_argument("--thinking", default=os.environ.get("PI_THINKING"))
    ag.add_argument("--pi-tools", default="read,bash,edit,write,grep,find,ls")
    ag.add_argument("--prompt-template", type=Path, default=DEFAULT_TEMPLATE)
    ag.add_argument("--goal", help="追加到 prompt 的本批次优化目标")
    ag.add_argument("--agent-timeout", type=int, default=1800)
    ag.add_argument("--require-agent", action="store_true", help="agent 失败即判定课题失败（默认回退原源码继续渲染）")

    rd = p.add_argument_group("渲染与产物")
    rd.add_argument("--work-root", type=Path, default=Path(os.environ.get("MANIM_WORK_ROOT", "/tmp/manim_math")))
    rd.add_argument("--run-id", default=dt.datetime.now().strftime("%Y%m%d-%H%M%S"))
    rd.add_argument("--resume", action="store_true", help="跳过本 run-id 下已成功的课题")
    rd.add_argument("--quality", choices=tuple(QUALITY_FLAGS), default="l", help="l=480p15 预览, h=1080p60 正式")
    rd.add_argument("--resolution", default="1080,1920", help="输出 W,H（竖屏默认 1080,1920）")
    rd.add_argument("--render-timeout", type=int, default=1800)
    rd.add_argument("--no-render", action="store_true")
    rd.add_argument("--no-fallback-original", dest="fallback_original", action="store_false",
                    help="agent 版本渲染失败时不回退原源码重试")
    rd.add_argument("--strict-static", action="store_true", help="audit_scene 有 ERROR 即失败")
    rd.add_argument("--music", type=Path, help="授权背景音乐，例如 files/Away.mp3；生成 *_finish.mp4")
    rd.add_argument("--extract-to-repo", action="store_true", help="把成片复制回对应课程目录")
    rd.add_argument("--overwrite", action="store_true", help="课程目录已有同名视频时覆盖（默认另存 *_new.mp4）")
    rd.add_argument("--new-suffix", default="_new")
    rd.add_argument("--apply-source", action="store_true", help="门禁全部通过后把 agent 修改的源码写回仓库")
    rd.add_argument("--jobs", "-j", type=int, default=1)
    args = p.parse_args(argv)
    if args.agent == "custom" and not args.agent_cmd:
        p.error("--agent custom 需要 --agent-cmd")
    if not re.fullmatch(r"\d+,\d+", args.resolution):
        p.error("--resolution 形如 1080,1920")
    if not re.fullmatch(r"[\w.-]+", args.run_id):
        p.error("--run-id 只能包含字母数字 . _ -")
    args.work_root = args.work_root.resolve()
    return args


def main(argv=None) -> int:
    args = parse_args(argv)
    lessons = select_lessons(args)
    if not lessons:
        log("没有匹配的课题")
        return 2
    if args.list:
        for l in lessons:
            print(f"{l.topic_id}\t{l.level}\t{l.py_file}")
        return 0
    if not args.no_render and not shutil.which("ffmpeg"):
        log("ERROR: 需要 ffmpeg")
        return 2
    run_dir = args.work_root / "runs" / args.run_id
    run_dir.mkdir(parents=True, exist_ok=True)
    (run_dir / "args.json").write_text(json.dumps({k: str(v) for k, v in vars(args).items()},
                                                  ensure_ascii=False, indent=2), encoding="utf-8")
    log(f"批次 {args.run_id}: {len(lessons)} 课 → {run_dir}（agent={args.agent}, quality={args.quality}, jobs={args.jobs}）")

    reports: list[dict] = []

    def work(item: tuple[int, Lesson]) -> dict:
        idx, lesson = item
        job = LessonJob(lesson, args, run_dir)
        if args.resume and job.already_done():
            log(f"[{idx}/{len(lessons)}] ⏭  {lesson.py_file}（已完成）")
            return json.loads(job.report_path.read_text(encoding="utf-8"))
        log(f"[{idx}/{len(lessons)}] ▶  {lesson.py_file}")
        try:
            report = job.execute()
        except Exception as exc:  # 单课异常不影响整批
            report = {"ok": False, "topic_id": lesson.topic_id, "py_file": lesson.py_file, "scene": lesson.scene,
                      "steps": {"prepare": {"status": "fail", "detail": f"{type(exc).__name__}: {exc}"}},
                      "outputs": {}}
            job.dir.mkdir(parents=True, exist_ok=True)
            job.report_path.write_text(json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
        flags = " ".join(f"{k}:{v['status']}" for k, v in report["steps"].items())
        log(f"[{idx}/{len(lessons)}] {'✅' if report['ok'] else '❌'} {lesson.py_file} | {flags}")
        return report

    items = list(enumerate(lessons, 1))
    if args.jobs > 1:
        with cf.ThreadPoolExecutor(max_workers=args.jobs) as pool:
            reports = list(pool.map(work, items))
    else:
        reports = [work(item) for item in items]

    summary = write_summary(run_dir, reports)
    ok = sum(r["ok"] for r in reports)
    log(f"完成：{ok}/{len(reports)} 成功；汇总 {summary}；成片目录 {args.work_root / 'final'}")
    return 0 if ok == len(reports) else 1


if __name__ == "__main__":
    sys.exit(main())

