def validate_script_moves() -> list[str]:
    """Root legacy shell entry points must stay as wrappers that reference their new script."""
    errors: list[str] = []
    try:
        moves = json.loads((ROOT / "catalog/script-moves.json").read_text(encoding="utf-8"))
        if moves["schemaVersion"] != 1:
            errors.append("script-moves schemaVersion mismatch")
        for move in moves["moves"]:
            src, dst = ROOT / move["from"], ROOT / move["to"]
            if not src.is_file() or not dst.is_file():
                errors.append(f"missing script or legacy wrapper: {move['from']} -> {move['to']}")
            elif move["to"] not in src.read_text(encoding="utf-8").replace("{linux,macos}", "linux") \
                    and Path(move["to"]).name.replace("_macos", "_linux") not in src.read_text(encoding="utf-8").replace("$(uname -s)", ""):
                errors.append(f"legacy wrapper does not reference target: {move['from']} -> {move['to']}")
            elif not os.access(dst, os.X_OK):
                errors.append(f"script not executable: {move['to']}")
    except (OSError, ValueError, KeyError, TypeError) as exc:
        errors.append(f"script-moves error: {exc}")
    return errors

